package graphics

import "slices"

type Path struct {
	data []float32
}

type PathOperation float32

const (
	PathMoveTo   PathOperation = iota // (x, y)
	PathLineTo                        // (x, y)
	PathArcTo                         // (rx, ry, xRotate, large, sweep, x, y)
	PathBezierTo                      // (c1x, c1y, c2x, c2y, x, y)
	PathClose                         // (0, 0)
	// PathHole marks a subtractive contour generated by a shape constructor.
	// Its segments use the opposite winding to the enclosing contour.
	PathHole // (0, 0)
)

func (op PathOperation) String() string {
	switch op {
	case PathMoveTo:
		return "MoveTo"
	case PathLineTo:
		return "LineTo"
	case PathArcTo:
		return "ArcTo"
	case PathClose:
		return "Close"
	case PathHole:
		return "Hole"
	case PathBezierTo:
		return "BezierTo"
	default:
		return ""
	}
}

func MoveTo(x, y float32) Path {
	return Path{}.MoveTo(x, y)
}

// Grow reserves space for n additional float32 entries in the instruction
// buffer without changing the path. A negative n panics.
func (p Path) Grow(n int) Path {
	p.data = slices.Grow(p.data, n)
	return p
}

// MoveTo starts a new contour without discarding earlier contours.
func (p Path) MoveTo(x, y float32) Path {
	p.data = append(p.data, float32(PathMoveTo), x, y)
	return p
}

func (p Path) LineTo(x, y float32) Path {
	p.data = append(p.data, float32(PathLineTo), x, y)
	return p
}

func (p Path) ArcTo(rx, ry, xRotate, large, sweep, x, y float32) Path {
	p.data = append(p.data, float32(PathArcTo), rx, ry, xRotate, large, sweep, x, y)
	return p
}

func (p Path) BezierTo(c1x, c1y, c2x, c2y, x, y float32) Path {
	p.data = append(p.data, float32(PathBezierTo), c1x, c1y, c2x, c2y, x, y)
	return p
}

func (p Path) Close() Path {
	p.data = append(p.data, float32(PathClose), 0, 0)
	return p
}

// Hole marks the current contour as subtractive without moving the current
// point. Its segments must wind opposite to the enclosing contour.
func (p Path) Hole() Path {
	p.data = append(p.data, float32(PathHole), 0, 0)
	return p
}

func (p Path) Range(f func(op PathOperation, args []float32) (stop bool)) {
	var args []float32
	for i := 0; i < len(p.data); i++ {
		op := PathOperation(p.data[i])
		switch op {
		case PathMoveTo, PathLineTo, PathClose, PathHole:
			args = p.data[i+1 : i+3]
		case PathArcTo:
			args = p.data[i+1 : i+8]
		case PathBezierTo:
			args = p.data[i+1 : i+7]
		}
		if f(op, args) {
			return
		}
		i += len(args)
	}
}

// CurrentPos returns the last drawing point. Close returns to the current
// contour's start; contour markers do not move the point. An empty path is at 0,0.
func (p Path) CurrentPos() (x, y float32) {
	var startX, startY float32
	p.Range(func(op PathOperation, args []float32) bool {
		switch op {
		case PathMoveTo:
			startX, startY = args[0], args[1]
			x, y = startX, startY
		case PathLineTo, PathArcTo, PathBezierTo:
			x, y = args[len(args)-2], args[len(args)-1]
		case PathClose:
			x, y = startX, startY
		}
		return false
	})
	return
}
